@transaction.atomic
def seed_questions():
    subject = Subject.objects.filter(
        name__iexact="math",
        class_name__iexact="class 2"
    ).first()

    if not subject:
        subject = Subject.objects.create(
            name="math",
            class_name="class 2"
        )

    created = 0
    updated = 0

    for item in QUESTIONS:
        question, was_created = Question.objects.get_or_create(
            subject=subject,
            question_text=item["question_text"],
            defaults={
                "topic": item["topic"],
                "question_type": item["question_type"],
                "difficulty": item["difficulty"],
                "marks": item["marks"],
                "correct_answer": item["correct_answer"],
                "explanation": item["explanation"],
                "is_active": True,
            }
        )

        if not was_created:
            question.topic = item["topic"]
            question.question_type = item["question_type"]
            question.difficulty = item["difficulty"]
            question.marks = item["marks"]
            question.correct_answer = item["correct_answer"]
            question.explanation = item["explanation"]
            question.is_active = True
            question.save()
            updated += 1
        else:
            created += 1

        if item["question_type"] == "MCQ":
            question.options.all().delete()

            for order, (option_text, is_correct) in enumerate(
                item["options"], start=1
            ):
                QuestionOption.objects.create(
                    question=question,
                    option_text=option_text,
                    is_correct=is_correct,
                    option_order=order,
                )

    print("======================================")
    print("Class 2 Maths question bank processed")
    print(f"Questions processed: {len(QUESTIONS)}")
    print(f"Created: {created}")
    print(f"Updated: {updated}")
    print("======================================")


seed_questions()

